mapper.select:
SELECT s.statistics_id, s.player_id, s.player_name, s.team_id, s.played_matches, s.goals, s.assists, s.penalties,
       s.season, s.league, t.team_id, t.name AS team_name, t.logo
FROM statistics s
INNER JOIN team t ON s.team_id = t.team_id
WHERE s.league = #{league} AND s.season = #{season}
ORDER BY s.goals DESC;
